def convertir_anciens_rdv(apps, schema_editor):
    CreneauRdv = apps.get_model('planning', 'CreneauRdv')
    for c in CreneauRdv.objects.select_related('salle').iterator():
        c.nature, c.domaine = CORRESPONDANCE.get(c.type_rdv, ('AUTRE', 'SOCIAL'))
        if c.salle_id and c.mds_id is None:
            c.mds_id = c.salle.mds_id
        c.save(update_fields=['nature', 'domaine', 'mds'])


